import Crypto
import Foundation

/// A secret key known only to the verifier, for one more keyed pass over every digest.
///
/// NIST SP 800-63B-4 §3.1.1.2: "verifiers SHOULD perform an additional iteration of a keyed
/// hashing or encryption operation using a secret key known only to the verifier. If used, this
/// key value SHALL be generated by an approved random bit generator … The secret key value SHALL
/// be stored separately from the hashed passwords. It SHOULD be stored and used within a
/// hardware-protected area." So: generated from the caller's generator
/// (`SystemRandomNumberGenerator` in production), kept in its own owner-only file, never beside
/// the verifiers. **It isn't hardware-protected here**: a file is what every platform this
/// package targets can share. With it, a copy of the verifiers file alone is useless to a
/// guesser, which is the point.
// Justification: `key` is an immutable `let` and SymmetricKey is a value type; swift-crypto on Linux does not mark it Sendable, CryptoKit on Apple platforms does.
public struct Pepper: @unchecked Sendable {
    let key: SymmetricKey

    /// A fingerprint, for the scheme identifier: the first 8 bytes of SHA-256 of the key, in hex.
    /// It names which pepper a digest needs, and says nothing about the key.
    public let identifier: String

    /// Loads a pepper, refusing a file anyone but its owner can reach.
    ///
    /// - Parameter url: The pepper file.
    /// - Throws: ``KeyFileFailure``, or the error reading the file.
    public init(contentsOf url: URL) throws {
        let data = try KeyFile.read(url)
        key = SymmetricKey(data: data)
        identifier = SHA256.hash(data: data).prefix(8).map(Hex.byte).joined()
    }

    /// Writes a new pepper, owner-only, from a generator you supply. Never overwrites.
    ///
    /// - Parameters:
    ///   - url: Where to write it. Not beside the verifiers file.
    ///   - generator: An approved random bit generator in production (§3.2.12).
    /// - Throws: ``KeyFileFailure``.
    public static func create<Generator: RandomNumberGenerator>(at url: URL, using generator: inout Generator) throws {
        try KeyFile.create(at: url, using: &generator)
    }
}

/// Any passphrase scheme, with a pepper: HMAC-SHA-256 under the pepper, over the scheme's own
/// output.
///
/// The identifier is the base's with `+p<fingerprint>`, so a digest says which pepper it needs.
/// Adding a pepper or rotating one is then a new identifier, which
/// ``PassphraseVerifier/needsUpgrade(to:)`` already reports; during a rotation, list both
/// peppered schemes in ``PassphraseSchemes`` and write the new one.
public struct PepperedScheme: PassphraseScheme {
    private let base: any PassphraseScheme
    private let pepper: Pepper

    /// `base`, peppered.
    ///
    /// - Parameters:
    ///   - base: The scheme whose output is peppered.
    ///   - pepper: The pepper.
    public init(_ base: any PassphraseScheme, pepper: Pepper) {
        self.base = base
        self.pepper = pepper
    }

    /// The base's identifier and the pepper's fingerprint: `pbkdf2-sha256-c1+p<hex>`.
    public var identifier: String { "\(base.identifier)+p\(pepper.identifier)" }

    /// The base's.
    public var canonicalization: PassphraseCanonicalization? { base.canonicalization }

    /// The base's.
    public func isValid(parameters: String) -> Bool { base.isValid(parameters: parameters) }

    /// The base's derivation, then HMAC-SHA-256 under the pepper.
    public func derive(_ material: [UInt8], parameters: String, salt: [UInt8]) throws -> [UInt8] {
        let inner = try base.derive(material, parameters: parameters, salt: salt)
        return Array(HMAC<SHA256>.authenticationCode(for: inner, using: pepper.key))
    }

    /// The base's.
    public func isBelowCurrentCost(_ parameters: String) -> Bool { base.isBelowCurrentCost(parameters) }
}
